{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic project-level Editor role assigned",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The project-level roles/editor basic role grants broad permissions across many GCP services, exceeding least-privilege access for both listed users."
    },
    {
      "check_id": "CKV_GCP_49",
      "title": "Project role permits service account privilege escalation",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The broad Editor role can enable management of resources using service account identities, creating a path to access service account privileges beyond the users' intended permissions."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/browser\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}\n",
  "fix_summary": "Replaced the broad basic Editor role with the predefined Browser role, which provides limited project visibility without resource modification or service account impersonation capabilities."
}
